import { test, expect } from '@playwright/test';

test.describe('Notification Count Reset', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should reset notification count to zero after reading all messages', async ({ page }) => {
    // Verify initial notification count is displayed
    const notificationCount = page.getByRole('heading', { name: /notifications/i });
    await expect(notificationCount).toBeVisible();
    const countText = page.getByText(/3 notifications/i);
    await expect(countText).toBeVisible();

    // Verify read button is visible
    const readButton = page.getByRole('button', { name: /read all/i });
    await expect(readButton).toBeVisible();

    // Click read button to read all messages
    await readButton.click();

    // Verify notification count is reset to zero
    await expect(countText).toContainText(/0 notifications/i);

    // Verify read all button is disabled
    await expect(readButton).toBeDisabled();

    // Verify notification messages are no longer visible
    const messages = page.getByRole('listitem');
    await expect(messages).not.toBeVisible();

    // Verify notification count is now zero
    const countText = page.getByText(/0 notifications/i);
    await expect(countText).toBeVisible();

    // Verify notification icon is hidden
    const notificationIcon = page.getByRole('img', { name: /notification/i });
    await expect(notificationIcon).not.toBeVisible();
  });

  test('should not reset notification count if there are unread messages', async ({ page }) => {
    // Verify initial notification count is displayed
    const notificationCount = page.getByRole('heading', { name: /notifications/i });
    await expect(notificationCount).toBeVisible();
    const countText = page.getByText(/3 notifications/i);
    await expect(countText).toBeVisible();

    // Verify read all button is visible
    const readButton = page.getByRole('button', { name: /read all/i });
    await expect(readButton).toBeVisible();

    // Verify notification messages are visible
    const messages = page.getByRole('listitem');
    await expect(messages).toBeVisible();

    // Verify notification count is not zero
    await expect(countText).toContainText(/3 notifications/i);

    // Verify read all button is still enabled
    await expect(readButton).toBeEnabled();

    // Verify notification icon is visible
    const notificationIcon = page.getByRole('img', { name: /notification/i });
    await expect(notificationIcon).toBeVisible();

    // Click read all button to read unread messages
    await readButton.click();

    // Verify notification count is still not zero
    await expect(countText).toContainText(/3 notifications/i);

    // Verify read all button is now disabled
    await expect(readButton).toBeDisabled();

    // Verify notification messages are still visible
    await expect(messages).toBeVisible();

    // Verify notification icon is still visible
    await expect(notificationIcon).toBeVisible();
  });
});
